from .core import *

def dn(prompt,value,note,model=None):
    t=number(prompt,value,note,model=model);t['format']='decimal';t['answer']=dec(value,6);t['success']='Верно! Ответ: '+dec(value,6)+'.';return t

def dx(a,b,op,note,prompt=None):
    t=expr(prompt or f'{dec(a)} {op} {dec(b)} = ?',a,b,op,note);t['format']='decimal';t['answer']=dec(t['answer'],6);t['success']='Верно! Ответ: '+t['answer']+'.';return t

def make(family,v,n):
    a=F(12+v,10);b=F(3+v%5,10);c=F(25+v,100);k=2+v%4
    if family=='decimal_intro':
        tasks=[shade(3+v%5,10),choice(f'{3+v%5}/10 — это…',dec(b),[dec(b),str(3+v%5),dec(b/10)],'После запятой первый разряд — десятые.'),dn(f'Запиши {12+v}/10 десятичной дробью.',a,'Отдели целые и десятые.'),choice(f'Равны ли {dec(a)} и {dec(a)}0?','Да',['Да','Нет'],'Нули справа от дробной части не изменяют числа.'),choice('В числе 2,05 цифра 5 означает…','5 сотых',['5 десятых','5 сотых','5 единиц'],'Второй разряд после запятой — сотые.'),dn(f'Запиши {25+v}/100 десятичной дробью.',c,'Нужны два знака после запятой, включая нуль при необходимости.')]
        return package('Собери десятые и сотые',['Знаменатели 10, 100, 1000 позволяют записать дробь с запятой.','Количество знаков после запятой соответствует числу нулей в знаменателе.','Нули в конце дробной части можно добавлять и убирать.'],['7/100 = 0,07','Нуль в разряде десятых обязателен: 0,7 — другое число.'],'Запиши три равные десятичные дроби с разным количеством нулей справа.',tasks)
    if family=='decimal_read':
        tasks=[choice('Как читается 2,07?','Две целых семь сотых',['Две целых семь десятых','Две целых семь сотых','Двадцать семь'],'Считай разряды после запятой.'),dn(f'Запиши число: {k} целых пять десятых.',F(k)+F(1,2),'Целая часть перед запятой, десятые после неё.'),number(f'Запиши {dec(c)} обыкновенной дробью.',c,'Знаменатель сначала 100; затем можно сократить.'),dn(f'Запиши {v+1}/4 десятичной дробью.',F(v+1,4),'Приведи к знаменателю 100.'),choice('Как записать три целых пять тысячных?','3,005',['3,5','3,05','3,005'],'В тысячных три знака после запятой.'),number(f'Переведи {dec(a)} в обыкновенную дробь.',a,'Запиши число десятых и сократи, если возможно.')]
        return package('Переводчик дробей',['Читай целую часть, затем дробную с названием последнего разряда.','Для перевода в обыкновенную дробь убери запятую и выбери знаменатель 10, 100 или 1000.'],['1,25 = 125/100','После сокращения на 25 получаем 5/4 = 1 1/4.'],'Составь две пары равных обыкновенных и десятичных дробей и прочитай их вслух.',tasks)
    if family=='decimal_ray':
        t1=ray(3+v,10,20);t1['prompt']=f'Отметь точку {dec(F(3+v,10))}.'
        t2=ray(12+v,10,20);t2['prompt']=f'Отметь точку {dec(a)}.'
        tasks=[dn('От 0 до 1 десять одинаковых промежутков. Каков шаг?',F(1,10),'Единицу разделили на 10.'),t1,dn(f'Точка стоит на {4+v}-м делении от нуля. Шаг 0,1. Координата?',F(4+v,10),'Умножь число промежутков на 0,1.'),t2,choice(f'{dec(a)} лежит…','Между 1 и 2',['Между 0 и 1','Между 1 и 2','Правее 3'],'Целая часть равна 1.'),dn(f'Какое число на 0,1 правее {dec(a)}?',a+F(1,10),'Движение вправо увеличивает координату.')]
        return package('Десятичные остановки',['Шаг между соседними делениями должен быть одинаковым.','При шаге 0,1 от 0 до 1 будет 10 промежутков.'],['Отметь 1,3','Найди 1, затем отсчитай вправо три промежутка по 0,1.'],'Построй луч с шагом 0,1. Отметь 0,4; 0,9; 1,2.',tasks)
    if family=='decimal_compare':
        tasks=[choice('0,7 … 0,65. Выбери знак.','>',['<','>','='],'0,7 = 0,70. Сравни сотые.'),choice(f'{dec(a)} … {dec(a+F(1,100))}.','<',['<','>','='],'Целые части и десятые равны — сравни сотые.'),choice('1,50 … 1,5.','=',['<','>','='],'Конечный нуль не изменяет значение.'),order('Расположи по возрастанию.',['0,8','0,08','0,88','0,808'],'Допиши нули до одинакового числа разрядов.'),choice('Ученик решил: 0,12 > 0,9, потому что 12 > 9. Он прав?','Нет',['Да','Нет'],'Сравнивать нужно одинаковые разряды: 0,12 и 0,90.'),choice(f'{dec(a+F(1,100))} … {dec(a+F(2,100))}.','<',['<','>','='],'Начинай сравнение с целой части.')]
        return package('Кто правее запятой?',['Сначала сравни целые части, затем десятые, сотые и следующие разряды.','Количество цифр после запятой само по себе не определяет, какая дробь больше.'],['0,9 и 0,12','0,90 > 0,12: 9 десятых больше 1 десятой.'],'Запиши две десятичные дроби, между которыми лежит 1,25.',tasks)
    if family=='decimal_add':
        tasks=[dx(a,b,'+','Запиши запятую под запятой.'),dx(a+b,b,'−','Единицы вычитай из единиц, десятые из десятых.'),choice('Как правильно расположить 2,5 и 0,37 для сложения?','Запятая под запятой',['По правому краю без учёта запятой','Запятая под запятой','Целые части отдельно не нужны'],'Можно записать 2,50 + 0,37.'),dx(a,c,'+','Допиши нуль в конце дробной части.'),dx(a+b,c,'−','При необходимости займи единицу предыдущего разряда.'),dx(a,b,'+','Общая масса равна сумме масс.',f'Для школьной акции собрали {dec(a)} кг бумаги утром и {dec(b)} кг днём. Сколько всего?')]
        return package('Мастерская запятых',['Складывай и вычитай одинаковые разряды: запятая под запятой.','Недостающие знаки можно дополнить нулями справа.'],['2,5 + 0,37','2,50 + 0,37 = 2,87. Проверка: 2,87 − 0,37 = 2,50.'],'Придумай задачу о массе собранной бумаги. Реши и проверь обратным действием.',tasks)
    if family=='decimal_multiply':
        tasks=[dx(b,k,'×','Сложи одинаковую дробь несколько раз.'),choice('В произведении 1,2 × 0,3 сколько знаков после запятой до сокращения нулей?','2',['1','2','3'],'Сложи число десятичных знаков у множителей.'),dx(a,b,'×','Сначала умножь без запятых, затем отдели нужное число знаков.'),dx(c,10,'×','Умножение на 10 увеличивает число в 10 раз.'),choice('0,5 × 0,2 меньше 0,5?','Да',['Да','Нет'],'Умножение на положительное число меньше 1 уменьшает число.'),dx(a,k,'×','Число одинаковых отрезков умножь на длину одного.',f'Для макета нужны {k} одинаковые ленты по {dec(a)} м. Какова общая длина?')]
        return package('Умножаем мерки',['Умножай как натуральные числа. В результате отдели суммарное число знаков после запятых у множителей.','При нехватке цифр слева допиши нули.'],['0,4 × 0,3','4 × 3 = 12. Отделяем два знака: 0,12.'],'Вычисли площадь прямоугольника со сторонами 1,2 м и 0,5 м. Нарисуй схему.',tasks)
    if family=='decimal_divide':
        tasks=[dx(b*k,k,'÷','Дели как натуральное число, учитывая запятую.'),choice('Как заменить 1,2 ÷ 0,3?','12 ÷ 3',['12 ÷ 0,3','1,2 ÷ 3','12 ÷ 3'],'Увеличь делимое и делитель в одинаковое число раз.'),dx(a*b,b,'÷','Сделай делитель натуральным.'),dx(a,F(1,10),'÷','Деление на одну десятую увеличивает число в 10 раз.'),choice('Можно ли делить на 0?','Нет',['Да','Нет'],'Деление на нуль не определено.'),dx(a*k,a,'÷','Раздели общую длину на длину части.',f'Ленту {dec(a*k)} м режут на части по {dec(a)} м. Сколько частей получится?')]
        return package('Сколько мерок поместится?',['Чтобы делить на десятичную дробь, перенеси запятые в обоих числах на одинаковое число знаков вправо.','В делителе должно получиться натуральное число. Проверь частное умножением.'],['2,4 ÷ 0,6','24 ÷ 6 = 4. Проверка: 4 × 0,6 = 2,4.'],'Составь задачу на деление длины на равные части с десятичными числами.',tasks)
    if family in ['decimal_scale_mul','decimal_scale_div']:
        op='×' if family.endswith('mul') else '÷';values=[F(10),F(100),F(1000),F(1,10),F(1,100),F(1,1000)]
        tasks=[dx(a if i<3 else b,z,op,'Сначала реши: результат должен увеличиться или уменьшиться?') for i,z in enumerate(values)]
        return package('Лифт разрядов',['Умножение на 10, 100, 1000 сдвигает запятую вправо; деление — влево.','Умножение на 0,1; 0,01; 0,001 уменьшает число. Деление на них увеличивает.'],['3,6 ÷ 0,1','Это 36 десятых. Результат 36, а не 0,36.'],'Запиши четыре примера с числом 2,5: умножение и деление на 10 и на 0,1.',tasks)
    if family in ['approximate','rounding']:
        x=F(234+v*7,100);near=F((x*10+F(1,2)).numerator//(x*10+F(1,2)).denominator,10);whole=(x+F(1,2)).numerator//(x+F(1,2)).denominator
        tasks=[choice('Округлённая длина — это…','Приближённое значение',['Всегда точное значение','Приближённое значение','Ошибка измерения без смысла'],'При округлении часть точности теряется.'),dn(f'Округли {dec(x)} до целых.',whole,'Смотри на цифру десятых: 5–9 увеличивают целую часть.'),dn(f'Округли {dec(x)} до десятых.',near,'Смотри на цифру сотых.'),choice('3,46 округлили до десятых как 3,4. Верно?','Нет',['Да','Нет'],'Сотых 6, поэтому десятые увеличиваются: 3,5.'),dn(f'Результат измерения {dec(x)} м. Запиши приближённо до десятых метра.',near,'Укажи точность: до десятых.'),dn(f'Округли {k},95 до десятых.',k+1,'Девять десятых после увеличения дают новое целое.')]
        return package('Выбери нужную точность',['Округление заменяет число близким значением с нужной точностью.','Посмотри на следующую цифру: 0–4 оставляют сохраняемую цифру, 5–9 увеличивают её на 1.','Приближённое равенство обозначают знаком ≈.'],['4,27 ≈ 4,3','Округляем до десятых. Цифра сотых 7, поэтому 2 десятых превращаются в 3.'],'Измерь длину карандаша и запиши результат в сантиметрах точно по линейке и приближённо до целых.',tasks)
    if family in ['decimal_words','decimal_sequences','decimal_invent']:
        step=F(v+1,10);start=F(k,10)
        if family=='decimal_words':
            tasks=[dx(a,b,'+','Сложи длины частей пути.',f'Прошли {dec(a)} км, потом {dec(b)} км. Каков весь путь?'),dx(a+b,b,'−','Вычти использованную часть.',f'Было {dec(a+b)} л воды, использовали {dec(b)} л. Сколько осталось?'),dx(b,k,'×','Общая масса равна массе одной пачки, умноженной на количество.',f'{k} одинаковых пачек по {dec(b)} кг. Сколько это килограммов?'),dx(a*k,k,'÷','Общую длину раздели на число равных частей.',f'{dec(a*k)} м ткани поделили на {k} равных частей. Длина одной части?'),dn(f'Учебная цена 1 кг яблок — {400+v*20} ₸. Сколько стоят 0,5 кг?',F(400+v*20,2),'Половина килограмма стоит половину цены килограмма.'),dx(a,F(1,2),'÷','Число бутылок равно объёму, делённому на вместимость.',f'Для опыта приготовили {dec(a)} л воды. Сколько полулитровых мерок это составляет?')]
            title='Математика школьного дня'
        else:
            vals=[start+i*step for i in range(4)]
            tasks=[dn('Продолжи ряд: '+', '.join(dec(x) for x in vals)+', …',start+4*step,'Найди разность соседних членов.'),dn('Каков шаг ряда: '+', '.join(dec(x) for x in vals)+'?',step,'Вычти предыдущий член из следующего.'),dn(f'Ряд начинается с {dec(start)}, каждый раз +{dec(step)}. Третий член?',start+2*step,'От первого до третьего — два шага.'),choice('У ряда 0,1; 0,2; 0,4; 0,8 правило…','Умножать на 2',['Прибавлять 0,1','Умножать на 2','Делить на 2'],'Проверь правило на каждой паре соседних членов.'),dn('Следующий член: 0,8; 0,4; 0,2; …',F(1,10),'Каждый следующий вдвое меньше.'),dict(type='sequence',decimal=True,start=float(start),count=4,prompt=f'Придумай постоянный положительный шаг. После {dec(start)} запиши ещё четыре члена через точку с запятой.',note='Можно выбрать, например, шаг 0,1 или 0,25.',hint='Прибавляй одно и то же число четыре раза.',success='У твоей последовательности постоянный положительный шаг!')]
            title='Продолжи дробный узор'
        return package(title,['Выдели известные величины и вопрос. Выбери действие или правило.','В последовательности проверь предполагаемое правило на всех показанных переходах.'],['0,2; 0,5; 0,8; …','Каждый раз +0,3. Следующее число 1,1.'],'Составь свою последовательность из пяти десятичных дробей. Запиши правило и попроси одноклассника её продолжить.',tasks)
